#!/usr/bin/env python3
"""Build the two inspectable product-redesign prototypes from repository data."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import yaml

from domain_foundry_core.foundry import FoundryCompiler, load_golden_specs
from domain_foundry_core.foundry.loader import DEFAULT_PRINCIPLES, DEFAULT_REGISTRY

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / "docs" / "prototypes"


def _script_json(value: object) -> str:
    return json.dumps(value, ensure_ascii=False).replace("</", "<\\/")


def _knowledge() -> dict[str, Any]:
    registry = yaml.safe_load(DEFAULT_REGISTRY.read_text(encoding="utf-8")) or {}
    principles: list[dict[str, Any]] = []
    for path in sorted(DEFAULT_PRINCIPLES.glob("*.yaml")):
        document = yaml.safe_load(path.read_text(encoding="utf-8")) or {}
        discipline = str(document.get("discipline") or path.stem)
        for item in document.get("principles", []):
            principles.append({"discipline": discipline, **item})
    return {"sources": registry.get("sources", []), "principles": principles}


def _flow_data() -> dict[str, Any]:
    compiler = FoundryCompiler()
    knowledge = _knowledge()
    sources = {item["id"]: item for item in knowledge["sources"]}
    cases = []
    for spec in load_golden_specs():
        raw = spec.model_dump(mode="json")
        raw["source_records"] = [sources[source_id] for source_id in spec.source_ids]
        raw["owned_app_html"] = compiler.render_app(spec)
        raw["schema_sql"] = compiler.compile_ddl(spec)
        cases.append(raw)
    return {"cases": cases}


